// Build a temporary buffer and verify round-trip with CO_setUint8/CO_getUint8
std::string buf = FUZZ_PARAM_STR();
if (buf.size() < sizeof(uint8_t)) { buf.resize(sizeof(uint8_t), '\0'); }
uint8_t v = (uint8_t)(*FUZZ_PARAM(unsigned int) & 0xFFu);
CO_setUint8((void*)buf.data(), v);
uint8_t r = CO_getUint8((const void*)buf.data());
FUZZ_ASSERT(r == v, "CO_getUint8 must read back the same value written by CO_setUint8");
// Validation: ensured buffer has at least 1 byte; verified get/set round-trip.

// Build a temporary buffer and verify round-trip with CO_setUint16/CO_getUint16
std::string buf = FUZZ_PARAM_STR();
if (buf.size() < sizeof(uint16_t)) { buf.resize(sizeof(uint16_t), '\0'); }
uint16_t v = (uint16_t)(*FUZZ_PARAM(unsigned int) & 0xFFFFu);
CO_setUint16((void*)buf.data(), v);
uint16_t r = CO_getUint16((const void*)buf.data());
FUZZ_ASSERT(r == v, "CO_getUint16 must read back the same value written by CO_setUint16");
// Validation: ensured buffer has at least 2 bytes; verified get/set round-trip.

