FUZZ_ASSERT(s.dataOffset == 0, "OD_rwRestart must reset dataOffset to 0");

// NULL must be tolerated (no crash / no action)
OD_rwRestart(nullptr);

// Validation: Ensures function behavior both for valid stream and NULL pointer.

// Exercise OD_requestTPDO by attaching an extension with flagsPDO and requesting a TPDO for a subIndex
OD_extension_t ext = {};
OD_entry_t entry = {};
entry.extension = &ext;

// Compute a valid subIndex within the available flags bits
size_t flagsBytes = sizeof(ext.flagsPDO);
uint8_t subIndex = 0;
if (flagsBytes > 0) {
    subIndex = (uint8_t)(*FUZZ_PARAM(uint16_t) % (flagsBytes * 8));
    // Pre-set the bit to 1 so a request should clear it
    size_t b = subIndex / 8u;
    uint8_t m = (uint8_t)(1u << (subIndex % 8u));
    ext.flagsPDO[b] |= m;
}

OD_requestTPDO(&entry, subIndex);

// If flags exist, the bit corresponding to subIndex should be cleared
if (flagsBytes > 0) {
    size_t b = subIndex / 8u;
    uint8_t m = (uint8_t)(1u << (subIndex % 8u));
    FUZZ_ASSERT((ext.flagsPDO[b] & m) == 0, "OD_requestTPDO should clear the request bit when flags are available");
}

// Validation: Attaches an extension and verifies the request bit is cleared when OD_FLAGS_PDO_SIZE > 0.

// Exercise OD_TPDOtransmitted by inspecting flagsPDO via an attached extension
OD_extension_t ext = {};
OD_entry_t entry = {};
entry.extension = &ext;

size_t flagsBytes = sizeof(ext.flagsPDO);
uint8_t subIndex = 0;
bool_t expectTrue = 0;
if (flagsBytes > 0) {
    subIndex = (uint8_t)(*FUZZ_PARAM(uint16_t) % (flagsBytes * 8));
    // Set the bit to indicate TPDO has been transmitted
    size_t b = subIndex / 8u;
    uint8_t m = (uint8_t)(1u << (subIndex % 8u));
    ext.flagsPDO[b] |= m;
    expectTrue = 1;
}

bool_t got = OD_TPDOtransmitted(&entry, subIndex);
if (flagsBytes > 0) {
    FUZZ_ASSERT(got == expectTrue, "OD_TPDOtransmitted should reflect the flag bit state when flags are available");
} else {
    // When no flags are compiled in, function should safely return false
    FUZZ_ASSERT(got == 0, "OD_TPDOtransmitted must be false when no flags exist");
}

