import os
import random
from typing import List

# This generator produces a binary buffer suitable for fuzz stubs that expect
# arbitrary byte arrays, used as raw memory for CO_get/CO_set helpers and FIFO writes.
# Goals:
# - Provide lengths that are at least 1/2/4 bytes for respective tests.
# - Include interesting patterns: all-zero, all-FF, incrementing, decrementing,
#   aligned 2/4/8 sizes, and random payloads. Keep size <= 4096.
# - Deterministic given seed, but vary content per call.

MAX_SIZE = 4096

def _choose_lengths(rng: random.Random) -> List[int]:
    # Include a variety of useful sizes for consumers that will resize or read
    # 1, 2, or 4 bytes, and for FIFO tests (1..512 typical there).
    base = [1, 2, 4, 8, 16, 32, 64, 128, 255, 256, 257, 512, 1024]
    # Add some random sizes
    for _ in range(5):
        base.append(rng.randint(1, min(1024, MAX_SIZE)))
    # Shuffle and dedup while preserving first occurrences
    seen = set()
    out = []
    rng.shuffle(base)
    for v in base:
        if v not in seen:
            seen.add(v)
            out.append(v)
    return out[: rng.randint(1, min(5, len(out)))]

def _pattern_zero(n: int) -> bytes:
    return b"\x00" * n

def _pattern_ff(n: int) -> bytes:
    return b"\xFF" * n

def _pattern_inc(n: int, start: int = 0) -> bytes:
    return bytes(((start + i) & 0xFF) for i in range(n))

def _pattern_dec(n: int, start: int = 0xFF) -> bytes:
    return bytes(((start - i) & 0xFF) for i in range(n))

def _pattern_words_le(n: int, rng: random.Random) -> bytes:
    # Fill with 32-bit little-endian words, good for CO_set/getUint32
    out = bytearray()
    while len(out) < n:
        v = rng.getrandbits(32)
        out += v.to_bytes(4, 'little')
    return bytes(out[:n])

def _pattern_words_be(n: int, rng: random.Random) -> bytes:
    # Big-endian words to mix variety; still valid arbitrary bytes
    out = bytearray()
    while len(out) < n:
        v = rng.getrandbits(32)
        out += v.to_bytes(4, 'big')
    return bytes(out[:n])

def _pattern_random(n: int, rng: random.Random) -> bytes:
    return bytes(rng.getrandbits(8) for _ in range(n))

def _compose_chunks(rng: random.Random) -> bytes:
    # Build a buffer by concatenating several patterns with varied lengths.
    chunks: List[bytes] = []
    lengths = _choose_lengths(rng)
    for ln in lengths:
        choice = rng.randint(0, 7)
        if choice == 0:
            chunks.append(_pattern_zero(ln))
        elif choice == 1:
            chunks.append(_pattern_ff(ln))
        elif choice == 2:
            chunks.append(_pattern_inc(ln, rng.randint(0, 255)))
        elif choice == 3:
            chunks.append(_pattern_dec(ln, rng.randint(0, 255)))
        elif choice == 4:
            chunks.append(_pattern_words_le(ln, rng))
        elif choice == 5:
            chunks.append(_pattern_words_be(ln, rng))
        else:
            chunks.append(_pattern_random(ln, rng))
    buf = b"".join(chunks)
    # Ensure size constraints
    if len(buf) > MAX_SIZE:
        buf = buf[:MAX_SIZE]
    return buf

def _ensure_min_sizes(buf: bytes) -> bytes:
    # The stubs will resize the temporary buffer themselves if too small, but
    # providing at least 4 bytes ensures immediate validity for 8/16/32 helpers.
    if len(buf) < 4:
        return buf + b"\x00" * (4 - len(buf))
    return buf

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    buf = _compose_chunks(rng)
    buf = _ensure_min_sizes(buf)
    # Occasionally pick a single focused pattern to explore boundary conditions
    if rng.random() < 0.2:
        n = rng.choice([1, 2, 4, 8, 16, 32, 64, 128, 255, 256, 257, 512])
        kind = rng.randint(0, 5)
        if kind == 0:
            buf = _pattern_zero(n)
        elif kind == 1:
            buf = _pattern_ff(n)
        elif kind == 2:
            buf = _pattern_inc(n)
        elif kind == 3:
            buf = _pattern_dec(n)
        elif kind == 4:
            buf = _pattern_words_le(n, rng)
        else:
            buf = _pattern_random(n, rng)
        buf = _ensure_min_sizes(buf)
    return buf
